import Foundation
let dir=URL(fileURLWithPath:CommandLine.arguments[1],isDirectory:true),seed=try JSONSerialization.jsonObject(with:Data(contentsOf:dir.appendingPathComponent("seed.json"))) as! [String:Any],capture=try JSONSerialization.jsonObject(with:Data(contentsOf:dir.appendingPathComponent("server-responses.json"))) as! [String:Any]
func id(_ name:String)->UUID { UUID(uuidString:seed[name] as! String)! }
let human=id("principalId"),endpoint=id("endpointId"),enrollment=id("enrollmentId")
func policy(_ name:String)throws->MobileHealthPolicyProof { let body=try JSONSerialization.data(withJSONObject:capture[name]!);return try MobileHealthPolicyParser.parse(body,expectedPrincipal:human,expectedEndpoint:endpoint,expectedEnrollment:enrollment) }
func results(_ name:String)throws->[HealthDeliveryResult] { let all=capture["captured"] as! [[String:Any]],row=all.first{$0["case"] as? String==name}!;return try MobileHealthWire.receipt(JSONSerialization.data(withJSONObject:row["response"]!)) }
let allowed=try policy("eligiblePolicy"),narrow=try policy("narrowedPolicy");precondition(allowed.revision==3 && allowed.permitsCollection && allowed.healthKitTypes.contains("sleep"));precondition(narrow.revision==4 && !narrow.healthKitTypes.contains("sleep"))
let store=HealthOutbox(storage:ProtectedHealthFileStorage(file:dir.appendingPathComponent("outbox.json")));try store.setHuman(human);try store.confirmEffectivePolicy(proof:allowed);let ticket=try store.ticket(enrollment:enrollment,type:"sleep"),before=try store.pending(ticket:ticket);precondition(before.count==2 && before.allSatisfy{$0.expectedPolicyRevision==2})
let accepted=try results("oldN-currentNPlus1-allowed");precondition(accepted.count==1 && accepted[0].eventId==before[0].eventId && accepted[0].outcome == .accepted);try store.settle(ticket:ticket,accepted:[accepted[0].eventId],rejected:[:]);let afterAccepted=try store.pending(ticket:ticket);precondition(afterAccepted == [before[1]])
let rejected=try results("oldN-currentNPlus2-narrowed");precondition(rejected.count==1 && rejected[0].eventId==before[1].eventId && rejected[0].outcome == .rejected && rejected[0].code == .scope);try store.settle(ticket:ticket,accepted:[],rejected:[rejected[0].eventId:rejected[0].code]);let quarantineCount=try store.quarantinedCount(ticket:ticket);precondition(quarantineCount==1)
let duplicate=try results("already-applied-duplicate-after-narrowing");precondition(duplicate.count==1 && duplicate[0].eventId==accepted[0].eventId && duplicate[0].outcome == .duplicate);do{try store.settle(ticket:ticket,accepted:[duplicate[0].eventId],rejected:[:]);fatalError("duplicate outside local queue must not acknowledge anything")}catch{}
try store.narrow(enrollment:enrollment,types:[]);let status=try store.status(enrollment:enrollment);precondition(status.paused && status.pending==0 && status.quarantined==1)
do{_=try store.ticket(enrollment:enrollment,type:"sleep");fatalError("narrowed source must not retry")}catch{}
let unchanged=try MobileHealthWire.request(batch:MobileHealthEncoder.batch([before[1]],enrollment:enrollment,sourceNamespace:ticket.sourceNamespace,category:"sleep").data);let original=try Data(contentsOf:dir.appendingPathComponent("narrowed-request.json"));precondition(unchanged == original)
print("captured replay passed: accepted removed, rejected retained while narrowed, duplicate cannot ack absent item, exact N event body unchanged")
